-- From out-a.json, out-b.json, out-c.json. Cards: 271 (265 with changed Hebrew fields, 267 with changed English fields, 270 with seasonal notes).
-- Each card updates its place_library row and every candidates row with that library_id: 542 update statements.
-- Run it after supabase/sql/2026-11-18-seasonal-notes.sql (the seasonal column) and after the owner's Japan trip (toogo-rules 6).
-- One transaction. Safe to run twice: the backups keep the FIRST old values (a second run does not overwrite them), and the updates set the same values again.
-- Backups: place_library_backup_20261118_seasonal and candidates_backup_20261118_seasonal (rows as they were). Restore one card:
--   update public.place_library l set tip = b.tip, plan_line = b.plan_line, reality = b.reality, special = b.special, todo = b.todo, hype = b.hype,
--          baby_notes = b.baby_notes, baby_block = b.baby_block, highlights = b.highlights, en = b.en, seasonal = b.seasonal
--     from public.place_library_backup_20261118_seasonal b where b.id = l.id and l.id = '<id>';   -- the same for candidates

begin;

do $$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'place_library' and column_name = 'seasonal')
     or not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'candidates' and column_name = 'seasonal') then
    raise exception 'run supabase/sql/2026-11-18-seasonal-notes.sql first (the seasonal column is missing)';
  end if;
end $$;

