-- Yokohama Hakkeijima Sea Paradise
update public.place_library set tip = $s0$פתוח לפי מתקן ושעות משתנות. כרטיס אונליין זול יותר. כ-40 דקות משין-סאקוראגיצ'ו, אז לתכנן כחצי יום.$s0$, special = $s0$הופעת הדולפינים בערב, והזיקוקים הקצרים כל ערב.$s0$, todo = $s0$נכנסים לאקווריום (Aqua Museum), רואים את הדולפינים ואת האקווריום הגדול, ואם נשארים עד הערב רואים את הזיקוקים הקצרים ב-20:00.$s0$, plan_line = $s0$חצי יום, רחוק מהמלון. לבדוק שעות באתר$s0$, hype = $s0$פארק ים ענק עם אקווריום, דולפינים והופעות.$s0$, baby_notes = $s0$האקווריום נגיש לעגלות. השאלת עגלות דורשת הזמנה מראש (כ-250 ין). אין מידע על חדר הנקה ועל מדיניות תינוקות (בדרך כלל חינם).$s0$, highlights = array[$s0$אקווריום ודולפינים$s0$, $s0$זיקוקים קצרים$s0$]::text[], en = coalesce(en, '{}'::jsonb) || $s0${"tip":"Hours vary by attraction. Buying the ticket online is cheaper. About 40 minutes from Shin-Sakuragicho, so plan half a day.","special":"The evening dolphin show, and the short fireworks every evening.","todo":"Go into the Aqua Museum, see the dolphins and the big tank, and if you stay into the evening catch the short fireworks at 20:00.","plan_line":"Half a day, far from the hotel. Check hours on the site","hype":"A huge seaside park with an aquarium, dolphins and shows.","reality":"Nice but far, and a big site; only worth it with a free half day. Prices not verified.","baby_notes":"The aquarium is stroller accessible per booking sites, and stroller rental needs a reservation (about 250 yen). Nursing room and infant policy not verified (usually free).","highlights":["Aquarium and dolphins","Short fireworks"]}$s0$::jsonb, seasonal = $s0${"winter":{"he":"בחוץ קר ורוח.","en":"It is cold and windy outdoors."},"dated":[{"from":"2026-11-15","to":"2026-12-25","he":"בדרך כלל יש אירוע חג עם תאורה והופעת דולפינים בערב; בשנה שעברה הוא רץ מ-15.11 עד 25.12.","en":"There is usually a Christmas event with lights and an evening dolphin show; last year it ran from Nov 15 to Dec 25."},{"from":"2026-12-01","to":"2026-12-31","he":"שעות דצמבר 2026 לא אומתו, לבדוק באתר.","en":"December 2026 hours were not verified, check the site."}]}$s0$::jsonb where id = '42285910-3b1d-4682-9372-5a4d5b8afe9b';
