-- Yokohama Red Brick Warehouse
update public.place_library set tip = $s0$העומס הכי גדול בסופי שבוע. להגיע לקראת השקיעה ולראות את זה נדלק.$s0$, special = null, todo = $s0$מסתובבים בין החנויות ובתי הקפה בשני מבני הלבנים, ויוצאים לנמל שמאחור.$s0$, plan_line = $s0$הכי יפה בערב כשהכול מואר$s0$, hype = $s0$מבנה לבנים אדומות מ-1913 על הנמל, עם חנויות ובתי קפה.$s0$, baby_notes = $s0$המבנה ישר ושטוח, קל לעגלה.$s0$, highlights = array[$s0$מבנה לבנים מ-1913$s0$, $s0$נמל מואר$s0$, $s0$חנויות וקפה$s0$]::text[], en = coalesce(en, '{}'::jsonb) || $s0${"tip":"Weekends are the most crowded. Come near sunset and watch it light up.","special":null,"todo":"Wander between the shops and cafes in the two brick buildings, then go out to the harbour behind.","plan_line":"Prettiest in the evening when it is lit","reality":"Especially pretty in the evening when everything is lit. You can just walk around without buying.","hype":"A 1913 red brick building on the harbour, with shops and cafes.","baby_notes":"The building is flat and easy for a stroller.","highlights":["1913 brick buildings","Lit harbour","Shops and cafes"]}$s0$::jsonb, seasonal = $s0${"winter":{"he":"בחורף יש בכיכר שוק חג המולד בסגנון גרמני עם עץ אשוח אמיתי ודוכני יין חם ונקניקיות. הכניסה לשוק בתשלום קטן, בסופי שבוע צפוף ועומדים בחוץ בקור, אז להלביש את התינוק חם.","en":"In winter there is a German-style Christmas market in the square with a real fir tree and stalls of mulled wine and sausages. Entry to the market costs a little, weekends are crowded and you stand outside in the cold, so dress the baby warmly."},"dated":[{"from":"2026-11-20","to":"2026-12-25","he":"שוק חג המולד מתקיים 20.11 עד 25.12.","en":"The Christmas market runs 20 Nov to 25 Dec."}]}$s0$::jsonb where id = '9edbc143-9a5a-4ac0-8a78-b0a87088386d';
