-- Shibuya Sky
update public.place_library set tip = $s0$כדאי לבחור יום בהיר ולהתלבש בשכבות. אם מעונן עדיף לדלג, הגג החינמי של בניין העירייה בשינג'וקו הוא גיבוי זול.$s0$, en = coalesce(en, '{}'::jsonb) || $s0${"tip":"Pick a clear day and dress in layers. If it's cloudy, skip it, the free roof of the Shinjuku city hall building is a cheap backup."}$s0$::jsonb, seasonal = $s0${"winter":{"he":"בחורף קר ברוח והשקיעה בערך ב-16:30.","en":"Winter is cold and windy and sunset is around 16:30."},"summer":{"he":"בקיץ חם ולח על הגג הפתוח, ופוג'י נראה רק לעיתים רחוקות.","en":"Summer is hot and humid on the open roof, and Fuji is seldom visible."}}$s0$::jsonb where id = '33673010-2a66-46f1-8b13-c70991f0ff14';
