-- Tokyo Sea Life Park
update public.place_library set todo = $s0$אקווריום גדול על המפרץ, בתוך פארק Kasai Rinkai, עם מיכל ענק שאפשר לשבת מולו, פינגווינים ובית זכוכית עם נוף למים. אחר כך מטיילים בפארק שעל החוף ועולים על הגלגל הענק. מתכננים אקווריום חדש במקום הישן, אז כדאי לבדוק באתר מה פתוח.$s0$, en = coalesce(en, '{}'::jsonb) || $s0${"todo":"A big aquarium on the bay, inside Kasai Rinkai Park, with a giant tank you can sit in front of, penguins and a glass house with a view of the water. Afterward walk in the park on the waterfront and ride the Ferris wheel. They plan a new aquarium to replace the old one, so check the website for what's open."}$s0$::jsonb where id = 'e2e53179-a028-4f1c-86aa-4b382935e1c7';
